/// A manufacturer of the filter panel's list (MotorFilterPanel), in the list's order.
struct MotorChooserManufacturerPin
{
    std::string_view simpleName;
    std::string_view displayName;
    /// How many sets of the database it makes.
    std::size_t sets;
};

/// The motor mount of the mount scenarios: an inner tube of outer radius 14.5 mm and inner radius
/// 14 mm, 0.1 m long; its motor mount diameter and length.
