inline constexpr double kMotorChooserMountLength   = 0x1.999999999999ap-4;

/// What the table shows after a step of the probe (ThrustCurveMotorSelectionPanel's JTable).
struct MotorChooserRowScenarioPin
{
    /// The step's name.
    std::string_view name;
    /// The rows shown.
    std::size_t rows;
    /// The sort keys: "<column><A|D>" each, the primary first, separated by spaces.
    std::string_view sortKeys;
    /// The MD5 of every row's "<model row>\t<the six column texts, tab-separated>\n", in the
    /// table's order, as UTF-8.
    std::string_view md5;
    /// The first rows (at most ten): their index in kMotorChooserRowPins and how many.
    std::size_t firstRow;
    std::size_t firstRowCount;
};

/// The filter's limits after a step (MotorRowFilter); a diameter limit OpenRocket has not set is
/// none.
struct MotorChooserFilterPin
{
    std::string_view name;
    bool             hasMinimumDiameter;
    double           minimumDiameter;
    bool             hasMaximumDiameter;
    double           maximumDiameter;
    double           minimumLength;
    double           maximumLength;
};

/// A set of more than one curve selected through the table of a fresh chooser: the curve selected
/// and the curve list.
struct MotorChooserCurvePin
{
    /// Its index in ThrustCurveMotorSetDatabase.getMotorSets().
    std::size_t setIndex;
    /// The selected curve: an index into the set's getMotors().
    std::size_t selectedCurve;
    /// The curve list: the set indices of its curves, in its order, separated by ','.
    std::string_view curves;
};

/// A curve of a set of more than one curve that OpenRocket's panel, opened for it
/// (setMotorMountAndConfig()), does not end on: its curve box re-enters select() (see
/// ThrustCurveMotorSelection's deviations).
struct MotorChooserCurveBoxElsewherePin
{
    std::size_t setIndex;
    /// The curve opened for: an index into the set's getMotors().
    std::size_t curve;
    /// The curve OpenRocket ends on.
    std::size_t selectedCurve;
};

/// The selection panel after a path that refills the curve list outside the curve box's own
/// action event, with "Hide very similar thrust curves" on.
struct MotorChooserCurveBoxPin
{
    /// 'C': opened for the curve (setMotorMountAndConfig()); 'B': the curve stored as its set's
    /// preferred one (OK), then the set selected through the table of a new panel; 'A': the set
    /// selected through the table, "Hide very similar thrust curves" off, the curve chosen in the
    /// curve list, the box on again.
    char        path;
    std::size_t setIndex;
    /// The curve the path selects: an index into the set's getMotors().
    std::size_t curve;
    /// The curve OpenRocket ends on.
    std::size_t selectedCurve;
    /// The curve list: the set indices of its items' curves, separated by ','.
    std::string_view curves;
    /// The MotorHolder indices of the items (the plot colours), separated by ','.
    std::string_view holderIndices;
    /// The selected item of the curve list.
    std::size_t curveSelection;
    /// What getFilteredCurves() gives with the path's curve selected: the list the curve box's
    /// own choice of that curve shows (no re-entry), set indices separated by ','.
    std::string_view filteredCurves;
};

/// The selection panel after a step.
struct MotorChooserSelectionPin
{
    std::string_view label;
    /// The selected set's index in getMotorSets().
    std::size_t setIndex;
    /// The selected curve: an index into the set's getMotors().
    std::size_t      curve;
    std::string_view digest;
    double           delay;
    /// Whether the curve list is enabled (more than one curve).
    bool curvesEnabled;
    /// The curve list: the set indices of its curves, separated by ','.
    std::string_view curves;
    /// The selected item of the curve list.
    std::size_t curveSelection;
    /// The delay box's items, separated by '|'.
    std::string_view delayItems;
    /// The delay box's text.
    std::string_view delayText;
    double           nozzle;
};

/// The delay box after a text is typed into it (on Estes C6, each text after the one before).
struct MotorChooserDelayPin
{
    std::string_view typed;
    double           delay;
    std::string_view text;
};

/// The selection panel after setMotorMountAndConfig() for a motor configuration.
struct MotorChooserOpenPin
{
    std::string_view label;
    /// The digest of the selected curve.
    std::string_view digest;
    double           delay;
    double           nozzle;
    /// The curve list: the set indices of its curves, separated by ','.
    std::string_view curves;
    /// The delay box's items, separated by '|'.
    std::string_view delayItems;
    std::string_view delayText;
    /// The rows of the table's model, and the model row of the selected set.
    std::size_t modelRows;
    std::size_t setRow;
};

/// A key of the node of the preferred curves, and its value.
struct MotorChooserPreferredPin
{
    std::string_view digest;
    std::string_view value;
};

/// MotorClass for an impulse.
struct MotorChooserClassPin
{
    double           impulse;
    std::string_view name;
    std::string_view description;
    std::string_view classDescription;
};

